import collections
def md(o, inv):
    P, K, M = o['places'], o['kinds'], o['missing']
    g = collections.Counter(p['group'] for p in P)
    L = ['# INDOORS spec: every enterable indoor place and what furnishes it', '',
         'Generated by tools/city/rooms/builtin/indoors/make_spec.py (%s); data: map_dc/coronado/city_kit/interiors/builtin/indoors_spec.json.' % o['generated'],
         'Supersedes the per-shop prop lists of NEW-19 / NEW-21 (share/shops_trim/shop_props_plan.csv): same lists for the shops, plus every non-shop place.', '',
         '## Scope: %d places' % len(P), '']
    for k, v in g.items(): L.append('- %s: %d' % (k, v))
    L += ['- (Yasin 22 Nov: 100 kept shops + 78 real non-shop indoor places = 178; + the %d Strand/Adela m_gr_* shops kept because their kind exists nowhere else among kept shops.)' % g.get('Strand/Adela shop kept (one of a kind)', 0),
          '- Strand/Adela shops trimmed (NEW-18 rule: kind already kept elsewhere; building swapped or door closed, room row dropped): ' + ', '.join('%s (%s)' % (s['name'], s['kind']) for s in o['strand_swap']), '',
          '## Budgets (per place, Redmi Note class)', '',
          '- Building near tier: the interior shell is part of the one near mesh/material (vertex alpha 0 = indoor); it must fit the model class budget (pilot +700-800 tris). Mid/far stay closed, unchanged.',
          '- Glass 1 draw (alpha over the panes only, closes 24-30 m); doors: hinged DoorLeaf nodes; 1 breakable window per place max.',
          '- Props: drawn only within 30 m (PROP_END); merged to 1-2 draws per room; cap **25,000 tris** per room (big rooms trim stock count, never core props); 4 lights max, no shadows.',
          '- Collision: <= 12 boxes for the shell + one box per large prop.',
          '- New (missing) props: near tier only, kit indoor atlas pages (props_i_*), budgets below are maximums.', '',
          '## Missing props (maintained: make_spec fails if a kind names a prop no manifest has and this table lacks)', '',
          'Do not build yet (next job after indoors). Until built, the stand-in is placed in the slot.', '',
          '| prop | class | near tris max | size (w x d x h m) | stand-in now | used by kinds |', '|---|---|---|---|---|---|']
    for x, v in M.items(): L.append('| %s | %s | %s | %s | %s | %s |' % (x, v['class'], v['near_tris'], v['size_m'], v['stand_in'], ', '.join(v['used_by'])))
    tot = sum(v['near_tris'] for v in M.values())
    L += ['', '%d missing props, %d near tris if all built. Every prop the NEW-21 shop lists flagged as missing is now built (infoodsvc, inretailfx, insvcshop, intrade, inleisure, ingymx batches).' % (len(M), tot), '',
          '## Kinds (%d furnishing profiles, by dress_as)' % len(K), '', '| kind | places | core | stock / display | decor | missing | max prop tris est. | note |', '|---|---|---|---|---|---|---|---|']
    for k, v in sorted(K.items()):
        L.append('| %s | %d | %s | %s | %s | %s | %s%s | %s |' % (k, v['places'], ', '.join(v['core']), ', '.join(v['stock']), ', '.join(v['decor']), ', '.join(v['missing']) or '-',
                 v['prop_tris_max'], ' (trimmed to 25k in %d)' % v['over_cap'] if v['over_cap'] else '', v['note'].replace('|', '/')))
    L += ['', '## Places', '', '| # | id | name | kind -> dress | group | piece | model | room w x d m | size | row |', '|---|---|---|---|---|---|---|---|---|---|']
    for i, p in enumerate(sorted(P, key=lambda p: (p['group'], p['dress'], p['id'])), 1):
        L.append('| %d | %s | %s | %s%s | %s | %s | %s | %s x %s | %s | %s |' % (i, p['id'], p['name'], p['kind'], '' if p['dress'] == p['kind'] else ' -> ' + p['dress'], p['group'], p['piece'], p['model'],
                 p['w'] or '?', p['d'] or '?', p['size'] if p['w'] else '?', 'yes' if p['has_row'] else 'ADD'))
    L += ['', '## Variation (same kind never a copy)', '',
          '- 2-3 layout templates per kind archetype and footprint class, mirror, 2-3 decor sets, 3-4 colour palettes (instance colour; no extra draws).',
          '- seed = hash(room id); same-kind places sorted by id are dealt round-robin so neighbours of a kind never share a template; the bake records the pick.',
          '- The validator checks every template x mirror x kind x decor set (slots, required types, facing, collision, doors).', '']
    return '\n'.join(L) + '\n'
